public class Counter {
    private long count = 0; // Prone to data race and race condition
    private final Object lock = new Object();

    // Unsafe: Data race on 'count'
    public void incrementUnsafe() {
        count++; // Read-modify-write is not atomic
    }

    // Safe: Eliminates both data race and race condition
    public void incrementSafe() {
        synchronized (lock) {
            count++; // Establishes happens-before and mutual exclusion
        }
    }
}
